        "# STEP 5: Tenganisha Features na Targets\n",
        "\n",
        "# Targets (tunachotaka kutabiri)\n",
        "target_cols = ['PH', 'TOTAL HARDNESS (mg/L)', 'CONDUCTIVITY (µS/cm)']\n",
