        "    rmse = np.sqrt(mean_squared_error(y_test_df.iloc[:, i], y_pred_df.iloc[:, i]))\n",
        "    r2   = r2_score(y_test_df.iloc[:, i], y_pred_df.iloc[:, i])\n",
        "\n",
        "    print(f\"\\n--- {col} ---\")\n",
        "    print(f\"MAE  : {mae:.3f}\")\n",
